<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('purchases.create')&&!can('purchases.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';require __DIR__.'/purchase_helpers.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$db->beginTransaction();try{$lines=[];foreach($_POST['product_id']??[] as $i=>$id){if(!(int)$id)continue;$lines[]=['product_id'=>(int)$id,'quantity'=>(float)($_POST['quantity'][$i]??0),'unit_cost'=>(float)($_POST['unit_cost'][$i]??0),'update_prices'=>false];}$id=post_purchase($db,['supplier_id'=>(int)$_POST['supplier_id'],'supplier_invoice'=>trim($_POST['supplier_invoice']),'purchase_date'=>$_POST['purchase_date'],'discount'=>(float)$_POST['discount'],'tax'=>(float)$_POST['tax'],'paid_amount'=>(float)$_POST['paid_amount'],'due_date'=>$_POST['due_date'],'payment_method'=>$_POST['payment_method'],'reference_no'=>trim($_POST['reference_no']),'notes'=>trim($_POST['notes'])],$lines);$db->commit();flash('success','Purchase posted. Stock and supplier balance are updated automatically.');redirect('purchases.php');}catch(Throwable $e){$db->rollBack();flash('danger',$e->getMessage());redirect('purchase_new.php');}}
$suppliers=$db->query('SELECT * FROM suppliers WHERE status="active" ORDER BY name')->fetchAll();$products=$db->query('SELECT id,item_code,name,current_stock,avg_cost FROM products WHERE status="active" ORDER BY name')->fetchAll();page_start('Type a Purchase','purchases.php');?>
<div class="wizard-steps"><span class="active">1 Supplier Invoice</span><span>2 Products</span><span>3 Payment</span><span>4 Stock Updated</span></div><?php if(!$suppliers):?><div class="alert danger">Before receiving stock, <a href="suppliers.php"><b>add the supplier here</b></a>.</div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><div class="sale-layout"><section><article class="panel"><div class="panel-head"><div><span class="eyebrow">Step 1</span><h3>Copy details from the supplier invoice</h3></div></div><div class="form-grid"><label>Supplier<select name="supplier_id" required><option value="">Choose supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['supplier_code'].' - '.$s['name'])?></option><?php endforeach;?></select></label><label>Supplier invoice number<input name="supplier_invoice" placeholder="Example: INV-1001" required></label><label>Purchase date<input type="date" name="purchase_date" value="<?=date('Y-m-d')?>" required></label><label>Due date (only if money remains)<input type="date" name="due_date"></label></div></article><article class="panel table-panel" style="margin-top:20px"><div class="panel-head"><div><span class="eyebrow">Step 2</span><h3>Enter products received</h3></div><button type="button" class="btn secondary" id="add-line">+ Add Product</button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Current stock</th><th>Received qty</th><th>Buying cost each</th><th class="right">Amount</th><th></th></tr></thead><tbody id="lines"></tbody></table></div></article></section><aside class="panel sale-summary"><div class="panel-head"><div><span class="eyebrow">Step 3</span><h3>How much did you pay?</h3></div></div><div class="summary-row total"><span>Products total</span><strong id="subtotal">Rs. 0.00</strong></div><label>Invoice discount<input type="number" name="discount" id="discount" min="0" step=".01" value="0"></label><label>Tax<input type="number" name="tax" id="tax" min="0" step=".01" value="0"></label><div class="summary-row total"><span>Final total</span><strong id="total">Rs. 0.00</strong></div><label>Amount paid now<input type="number" name="paid_amount" id="paid" min="0" step=".01" value="0"></label><div class="summary-row"><span>Amount we still owe</span><b id="balance">Rs. 0.00</b></div><label>Paid using<select name="payment_method"><option value="cash">Cash</option><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option><option value="card">Card</option></select></label><label>Cheque / bank reference<input name="reference_no"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><div class="plain-help">When you click below, stock increases and buying cost is recalculated automatically.</div><button class="btn primary wide" style="margin-top:12px">Confirm & Add Stock</button></aside></div></form>
<template id="line-template"><tr><td><select name="product_id[]" class="product" required><option value="">Choose product</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" data-stock="<?=$p['current_stock']?>" data-cost="<?=$p['avg_cost']?>"><?=e($p['item_code'].' - '.$p['name'])?></option><?php endforeach;?></select></td><td class="stock">—</td><td><input type="number" name="quantity[]" class="qty" min=".001" step=".001" value="1" required></td><td><input type="number" name="unit_cost[]" class="cost" min="0" step=".01" required></td><td class="right amount">Rs. 0.00</td><td><button type="button" class="icon-button remove">×</button></td></tr></template><script>const lines=document.querySelector('#lines'),tpl=document.querySelector('#line-template'),fmt=n=>'Rs. '+n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function calc(){let sub=0;lines.querySelectorAll('tr').forEach(r=>{let a=(+r.querySelector('.qty').value||0)*(+r.querySelector('.cost').value||0);r.querySelector('.amount').textContent=fmt(a);sub+=a});let total=Math.max(0,sub-(+discount.value||0)+(+tax.value||0)),bal=Math.max(0,total-(+paid.value||0));subtotal.textContent=fmt(sub);document.querySelector('#total').textContent=fmt(total);balance.textContent=fmt(bal)}function add(){lines.append(tpl.content.cloneNode(true));calc()}add();addLine=document.querySelector('#add-line');addLine.onclick=add;lines.addEventListener('input',calc);lines.addEventListener('change',e=>{if(e.target.classList.contains('product')){let o=e.target.selectedOptions[0],r=e.target.closest('tr');r.querySelector('.stock').textContent=o.dataset.stock||'—';r.querySelector('.cost').value=o.dataset.cost||''}calc()});lines.addEventListener('click',e=>{if(e.target.classList.contains('remove')){e.target.closest('tr').remove();calc()}});discount.oninput=tax.oninput=paid.oninput=calc;</script><?php page_end();
